// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor, uint256 b1, uint256 b2, uint256 t) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        vm.assume(amount == 10 ether);

        uint256 n1 = bound(b1, 1, 1e18);
        uint256 d = bound(b2, 1, 1000);
        uint256 n2 = n1 + d;
        uint256 t1 = bound(t, 1, type(uint64).max - 2);

        // first valid call at block n1
        vm.roll(n1);
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        uint256 bal1 = address(c).balance;

        // second valid call at a strictly later block n2 and later timestamp
        vm.roll(n2);
        vm.warp(t1 + 1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        uint256 bal2 = address(c).balance;

        assertTrue(
            !(ok1 && ok2 && bal1 == 0 && bal2 == 0) || ((n2 - n1) % 15 == 0)
        );
    }
}
